tbd_array=0xFFFFFFFF
tcb_byte_count=0
threshold=0xE0,当transmit FIFO中有0xE0*8个字节，才开始发送
*/
struct cb{
	volatile uint16_t status;
	uint16_t cmd;
	uint32_t link;
	union{
		uint32_t ucode[UCODE_SIZE];
		struct{
			uint32_t tbd_array;
			uint16_t tcb_byte_count;
			uint8_t threshold;
			uint8_t tbd_count;
		}tcb;
		uint32_t simple_buffer_addr;
	}u;
	struct cb *next,*prev;
	dma_addr_t dma_addr;
};

