        private static char[] encodeHex(byte[] data) {
            int l = data.length;
            char[] out = new char[l << 1];
            for (int i = 0, j = 0; i < l; i++) {
                out[j++] = HEX_CHARS[(0xF0 & data[i]) >>> 4];
                out[j++] = HEX_CHARS[0x0F & data[i]];
            }
            return out;
        }

        /**
