// O(nlogn)
class Solution {
public:
    // events = { (start, end), ... }
    int maxEvents(vector<vector<int>>& events) {
        sort(events.begin(), events.end());

        int lastDay = 0;
        for (auto& e : events)
            lastDay = max(lastDay, e[1]);

        int result = 0;
        priority_queue<int> Q;  // min heap
        for (int i = 0, currDay = 1; currDay <= lastDay; currDay++) {
            // add new candidates
