function getJSTreeData(boxes) {
	var jstree_data;
	jstree_data = [];
	for (var i = 0; i < boxes.length; i++) {
		var box = boxes[i];
		var jstree_box = {};
		jstree_data.push(jstree_box);
		jstree_box.text = box.type;
		jstree_box.box = box;
		if (box.boxes) {
			jstree_box.children = getJSTreeData(box.boxes);
		} else if (box.entries) {
			jstree_box.children = getJSTreeData(box.entries);
		}
	}
	return jstree_data;
}

