void ProgCounter::timeString ( std::stringstream & ss,
    const time_t & elapsed ) const
{
    if ( elapsed < 60 ) ss << elapsed << " seconds";
    else if ( elapsed < 3600 ) ss << (1.0 * elapsed / 60.0) << " minutes";
    else ss << (1.0 * elapsed / 3600.0) << " hours";
}

