{
	const TypeDescriptor &sourceType = typeAndValue.GetTypeDescriptor();
	if (sourceType.IsPrimitiveType())
	{
		const Value resultValue = CastValue(typeAndValue, destType);
		TypeDescriptor nonConstDestType = destType;
